CASE BLUF: Short-interval (`<= 60 s`) inter-tower switches (`8 seconds` over `2.40 km`) reflect stationary RF load-balancing or cell-edge ping-pong handoff between overlapping macro sectors, NOT vehicle movement.
1. DIGITAL RECORD LITERACY: Adding a minimum dwell/separation filter (`dt_s >= 120` and `dist_km > 2 * macro_cell_radius_km`) prevents overlapping cell boundaries from being misclassified as physical transit.
2. INNOCENT ALTERNATIVE: A stationary handset sitting inside an apartment near the boundary of Tower A and Tower B toggles between both CGIs within seconds as multipath signal fades.
```python
def is_physical_transit_anomaly(
    dist_km: float,
    dt_s: int,
    overlap_radius_km: float = 3.5,
    max_kmh: float = 145.0,
) -> Dict[str, Any]:
    if dist_km <= overlap_radius_km and dt_s < 180:
        return {
            'classification': 'RF_BOUNDARY_PING_PONG_HANDOFF',
            'physical_violation': False,
        }
    kmh = dist_km / max(dt_s / 3600.0, 1e-6)
    return {
        'classification': 'IMPOSSIBLE_VELOCITY' if kmh > max_kmh else 'PLAUSIBLE_TRANSIT',
        'physical_violation': kmh > max_kmh,
        'implied_kmh': round(kmh, 1),
    }
```

CASE BLUF: Session-isolated Python EDA tracker binds history strictly to a per-subject `session_id` dictionary (or fresh `None`-guarded list) so cross-subject contamination is impossible.
1. AUDIT VERIFICATION: `SESSION_B` computes its baseline strictly from its own `2.0 uS` calibration window regardless of `SESSION_A`'s `9.5 uS` arousal history.
```python
def compute_session_eda_delta(samples: list[float], history: list[float] | None = None) -> dict:
    if history is None:
        history = []
    for s in samples:
        history.append(s)
    mean_val = sum(history) / len(history)
    return {"count": len(history), "baseline_mean": round(mean_val, 3), "latest_delta": round(samples[-1] - mean_val, 3)}

print("Subject A:", compute_session_eda_delta([8.5, 9.2, 9.8]))
print("Subject B:", compute_session_eda_delta([2.0, 2.1, 2.2]))
```

CASE BLUF: Tracking `visited` node IDs at enqueue time prevents exponential cycle explosion on undirected or cyclic evidence graphs while guaranteeing the shortest quote-backed path.
1. AUDIT FINDING: Every investigative graph contains reciprocal links (`person <-> phone <-> call <-> person`); without a `visited` set, BFS loops indefinitely.
```python
from collections import deque, defaultdict
from typing import List, Dict, Any, Optional

def bfs_quoted_shortest_path(
    edges: List[Dict[str, str]],
    start_node: str,
    goal_node: str,
) -> Optional[List[Dict[str, str]]]:
    adj: Dict[str, List[Dict[str, str]]] = defaultdict(list)
    for e in edges:
        if not e.get('doc_id') or not e.get('quote', '').strip():
            continue
        u, v = e['src'], e['dst']
        adj[u].append({'next': v, 'doc_id': e['doc_id'], 'quote': e['quote']})
        adj[v].append({'next': u, 'doc_id': e['doc_id'], 'quote': e['quote']})

    queue: deque[tuple[str, List[Dict[str, str]]]] = deque([(start_node, [])])
    visited: set[str] = {start_node}

    while queue:
        curr, path = queue.popleft()
        if curr == goal_node:
            return path
        for hop in adj[curr]:
            nxt = hop['next']
            if nxt not in visited:
                visited.add(nxt)
                queue.append((nxt, path + [{'from': curr, 'to': nxt, 'doc_id': hop['doc_id'], 'quote': hop['quote']}]))
    return None
```

CASE BLUF: Bidirectional Python manifest auditor verifies cryptographic file integrity and flags tampered digests, missing exhibits, and unlogged files inside the exhibit directory.
1. CUSTODY FINDING: An unindexed file sitting inside the exhibit folder violates First Officer intake discipline just as severely as a modified file.
```python
import hashlib
from pathlib import Path
from typing import Dict, Any, List

def sha256_disk(p: Path) -> str:
    h = hashlib.sha256()
    with p.open('rb') as f:
        for chunk in iter(lambda: f.read(65536), b''):
            h.update(chunk)
    return h.hexdigest()

def verify_custody_directory(exhibit_dir: Path, manifest_path: Path) -> Dict[str, Any]:
    expected: Dict[Path, str] = {}
    for line in manifest_path.read_text(encoding='utf-8').splitlines():
        if not line.strip():
            continue
        digest, rel_path = line.strip().split(None, 1)
        expected[Path(rel_path).resolve()] = digest.lower()

    actual_files = {p.resolve() for p in exhibit_dir.iterdir() if p.is_file() and not p.name.startswith('.')}
    missing: List[str] = []
    tampered: List[str] = []
    for exp_path, exp_hash in expected.items():
        if not exp_path.exists():
            missing.append(exp_path.name)
        elif sha256_disk(exp_path) != exp_hash:
            tampered.append(exp_path.name)
    unlogged = sorted(p.name for p in (actual_files - set(expected.keys())))
    return {
        'custody_intact': not (missing or tampered or unlogged),
        'missing_files': missing,
        'tampered_files': tampered,
        'unlogged_extra_files': unlogged,
    }
```
